// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 callCount, uint256 amount) public {
        vm.assume(callCount <= 10);
        vm.assume(amount > 0);
        vm.deal(address(this), amount * callCount);
        for (uint256 i = 0; i < callCount; i++) {
            (bool ok, ) = address(c).call{value: amount}("");
            require(ok, "receive failed");
        }
        assertEq(c.depositsCount(), callCount);
    }
}
